// Встроенные сжатые мемы из таблицы, чтобы они гарантированно открывались мгновенно на любом домене и пути.
export const BUILTIN_MEMES: Record<string, string> = {
  "meme-jojo-1.webp": "data:image/webp;base64,",
  "meme-jojo-2.webp": "data:image/webp;base64,",
  "meme-lighthouse.webp": "data:image/webp;base64,",
  "meme-tuda.webp": "data:image/webp;base64,",
  "meme-lahaine.webp": "data:image/webp;base64,",
  "meme-saburov.webp": "data:image/webp;base64,"
};

export function resolveMemeImageUrl(url: string): string {
  if (!url) return '';
  const trimmed = url.trim();
  if (trimmed.startsWith('data:')) return trimmed;
  for (const [fileName, dataUri] of Object.entries(BUILTIN_MEMES)) {
    if (trimmed.endsWith('/' + fileName) || trimmed === fileName) {
      return dataUri;
    }
  }
  return trimmed;
}
